data class BhaktiItem(val title: String, val text: String)

object BhaktiData {
    val items = listOf(
        BhaktiItem("ఆంజనేయ దండకం", "శ్రీ ఆంజనేయ స్వామి దండకం\n\nశ్రీ ఆంజనేయాయ నమః\nఓం శ్రీ హనుమతే నమః\n\nఆంజనేయం మహావీరం బ్రహ్మవిష్ణుమహేశ్వరమ్ ।\nశిలాతటాక సేతూనాం కర్తారం రామదూతకం ॥\n\nరామదూతాయ నమః । వాయుపుత్రాయ నమః ।\nభక్తరక్షకాయ నమః । సంకటమోచనాయ నమః ।\n\nగమనిక: పూర్తి దండక పాఠాన్ని సంప్రదాయ పాఠాంతరానుసారం ఈ విభాగంలో విస్తరించవచ్చు."),
        BhaktiItem("శ్రీ వేంకటేశ్వర సుప్రభాతం", "శ్రీ వేంకటేశ్వర సుప్రభాతం\n\nకౌసల్యా సుప్రజా రామ పూర్వాసంధ్యా ప్రవర్తతే ।\nఉత్తిష్ఠ నరశార్దూల కర్తవ్యం దైవమాహ్నికమ్ ॥\n\nఉత్తిష్ఠోత్తిష్ఠ గోవింద ఉత్తిష్ఠ గరుడధ్వజ ।\nఉత్తిష్ఠ కమలాకాంత త్రైలోక్యం మంగళం కురు ॥\n\nమాతస్సమస్త జగతాం మధుకైటభారేః\nవక్షోవిహారిణి మనోహర దివ్యమూర్తే ।\nశ్రీస్వామిని శ్రితజనప్రియ దానశీలే\nశ్రీ వేంకటేశ దయితే తవ సుప్రభాతమ్ ॥"),
        BhaktiItem("లలితా సహస్రనామం", "శ్రీ లలితా సహస్రనామ స్తోత్రం\n\nఓం శ్రీమాతా శ్రీమహారాజ్ఞీ శ్రీమత్సింహాసనేశ్వరీ ।\nచిదగ్నికుండసంభూతా దేవకార్యసముద్యతా ॥\n\nఉద్యద్భానుసహస్రాభా చతుర్బాహుసమన్వితా ।\nరాగస్వరూపపాశాఢ్యా క్రోధాకారాంకుశోజ్జ్వలా ॥\n\nమనోరూపేక్షుకోదండా పంచతన్మాత్రసాయకా ।\nనిజారుణప్రభాపూరమజ్జద్బ్రహ్మాండమండలా ॥\n\nసహస్రనామంలోని మిగిలిన నామాలను సంప్రదాయ పాఠాంతరం ప్రకారం ఈ పాఠ్య విభాగంలో ఉంచవచ్చు."),
        BhaktiItem("విష్ణు సహస్రనామం", "శ్రీ విష్ణు సహస్రనామ స్తోత్రం\n\nఓం శుక్లాంబరధరం విష్ణుం శశివర్ణం చతుర్భుజమ్ ।\nప్రసన్నవదనం ధ్యాయేత్ సర్వవిఘ్నోపశాంతయే ॥\n\nవ్యాసం వసిష్ఠనప్తారం శక్తేః పౌత్రమకల్మషమ్ ।\nపరాశరాత్మజం వందే శుకతాతం తపోనిధిమ్ ॥\n\nవిశ్వం విష్ణుర్వషట్కారో భూతభవ్యభవత్ప్రభుః ।\nభూతకృద్భూతభృద్భావో భూతాత్మా భూతభావనః ॥\n\nసహస్రనామంలోని మిగిలిన నామాలను సంప్రదాయ పాఠాంతరం ప్రకారం ఈ పాఠ్య విభాగంలో ఉంచవచ్చు."),
        BhaktiItem("శివ చాలీసా", "శ్రీ శివ చాలీసా\n\nజయ గణేశ గిరిజాసువన మంగళ మూల సుజాన ।\nకహత్ అయోధ్యాదాస తుమ్ దేహు అభయ వరదాన ॥\n\nజయ గిరిజాపతి దీనదయాలా । సదా కరత్ సంతన ప్రతిపాలా ॥\nభాల చంద్ర మా సోహత్ నీకే । కానన కుండల నాగఫణీ కే ॥\n\nఓం నమః శివాయ ।"),
        BhaktiItem("హనుమాన్ చాలీసా", "శ్రీ హనుమాన్ చాలీసా\n\nశ్రీగురుచరణ సరోజరజ నిజమనుముకురుసుధారి ।\nబరణౌ రఘువర బిమలజసు జో దాయకుఫలచారి ॥\n\nబుద్ధిహీన తను జానికే సుమిరౌ పవనకుమార ।\nబల బుద్ధి విద్యా దేహు మోహి హరహు కలేశ బికార ॥\n\nజయ హనుమాన జ్ఞాన గుణసాగర ।\nజయ కపీశ తిహుఁ లోక ఉజాగర ॥\n\nరామదూత అతులిత బలధామా ।\nఅంజనిపుత్ర పవనసుత నామా ॥\n\nశ్రీరామ జయరామ జయ జయ రామ ॥"),
        BhaktiItem("లక్ష్మీ అష్టోత్తర శతనామావళి", "శ్రీ లక్ష్మీ అష్టోత్తర శతనామావళి\n\nఓం ప్రకృత్యై నమః ।\nఓం వికృత్యై నమః ।\nఓం విద్యాయై నమః ।\nఓం సర్వభూతహితప్రదాయై నమః ।\nఓం శ్రద్ధాయై నమః ।\nఓం విభూత్యై నమః ।\nఓం సురభ్యై నమః ।\nఓం పరమాత్మికాయై నమః ।\nఓం వాచే నమః ।\nఓం పద్మాలయాయై నమః ।\n\nశ్రీ మహాలక్ష్మ్యై నమః ।"),
        BhaktiItem("శ్రీ దుర్గా చాలీసా", "శ్రీ దుర్గా చాలీసా\n\nనమో నమో దుర్గే సుఖ కరణీ । నమో నమో అంబే దుఃఖ హరణీ ॥\nనిరంకార హై జ్యోతి తుమ్హారీ । తిహూఁ లోక ఫైలీ ఉజియారీ ॥\n\nశశి లలాట ముఖ మహావిశాలా । నేత్ర లాల్ భృకుటి వికరాలా ॥\nరూప మాతు కో అధిక సుహావే । దర్శన కరత జనని మన భావే ॥"),
        BhaktiItem("ఆదిత్య హృదయం", "శ్రీ ఆదిత్య హృదయం\n\nతతో యుద్ధపరిశ్రాంతం సమరే చింతయాస్థితమ్ ।\nరావణం చాగ్రతో దృష్ట్వా యుద్ధాయ సముపస్థితమ్ ॥\n\nదైవతైశ్చ సమాగమ్య ద్రష్టుమభ్యాగతో రణమ్ ।\nఉపాగమ్యాబ్రవీద్రామమగస్త్యో భగవానృషిః ॥\n\nఆదిత్యహృదయం పుణ్యం సర్వశత్రువినాశనం ।\nజయావహం జపేన్నిత్యమక్షయం పరమం శుభమ్ ॥\n\nసర్వమంగళమాంగల్యం సర్వపాపప్రణాశనం ।\nచింతాశోకప్రశమనం ఆయుర్వర్ధనముత్తమమ్ ॥"),
        BhaktiItem("శ్రీ సూక్తం", "శ్రీ సూక్తం\n\nహిరణ్యవర్ణాం హరిణీం సువర్ణరజతస్రజామ్ ।\nచంద్రాం హిరణ్మయీం లక్ష్మీం జాతవేదో మ ఆవహ ॥\n\nతాం మ ఆవహ జాతవేదో లక్ష్మీమనపగామినీమ్ ।\nయస్యాం హిరణ్యం విందేయం గామశ్వం పురుషానహమ్ ॥\n\nఅశ్వపూర్వాం రథమధ్యాం హస్తినాదప్రబోధినీమ్ ।\nశ్రియం దేవీముపహ్వయే శ్రీర్మా దేవీర్జుషతామ్ ॥"),
        BhaktiItem("పురుష సూక్తం", "పురుష సూక్తం\n\nసహస్రశీర్షా పురుషః సహస్రాక్షః సహస్రపాత్ ।\nస భూమిం విశ్వతో వృత్వా అత్యతిష్ఠద్దశాంగులమ్ ॥\n\nపురుష ఏవేదం సర్వం యద్భూతం యచ్చ భవ్యం ।\nఉతామృతత్వస్యేశానో యదన్నేనాతిరోహతి ॥\n\nఏతావానస్య మహిమా అతో జ్యాయాంశ్చ పూరుషః ।\nపాదోఽస్య విశ్వా భూతాని త్రిపాదస్యామృతం దివి ॥")
    )
}
